import { readFileSync } from 'node:fs';

// Generated by scripts/generate-subpath-map.mjs from the @punji/ui package exports.
const SUBPATHS = JSON.parse(readFileSync(new URL('../data/subpath-map.json', import.meta.url), 'utf8'));

const nameOf = (spec) => spec.imported.name ?? spec.imported.value;

/** @type {import('eslint').Rule.RuleModule} */
export default {
  meta: {
    type: 'suggestion',
    fixable: 'code',
    docs: { description: 'Prefer @punji/ui/<module> subpath imports over the root barrel when a file imports only a few names.' },
    schema: [{ type: 'object', properties: { maxNames: { type: 'integer', minimum: 1 } }, additionalProperties: false }],
    messages: { subpath: 'Import from the subpath ({{targets}}) instead of the @punji/ui root barrel.' },
  },
  create(context) {
    const maxNames = context.options[0]?.maxNames ?? 3;
    const { sourceCode } = context;
    return {
      ImportDeclaration(node) {
        if (node.source.value !== '@punji/ui' || node.specifiers.length === 0) return;
        if (node.specifiers.some((s) => s.type !== 'ImportSpecifier') || node.specifiers.length > maxNames) return;
        const groups = new Map();
        for (const spec of node.specifiers) {
          const target = SUBPATHS[nameOf(spec)];
          if (!target) return; // unknown name: leave the whole import alone
          groups.set(target, [...(groups.get(target) ?? []), spec]);
        }
        const typeKw = node.importKind === 'type' ? 'type ' : '';
        context.report({
          node,
          messageId: 'subpath',
          data: { targets: [...groups.keys()].join(', ') },
          fix: (fixer) => fixer.replaceText(node, [...groups].map(([target, specs]) => `import ${typeKw}{ ${specs.map((s) => sourceCode.getText(s)).join(', ')} } from '${target}';`).join('\n')),
        });
      },
    };
  },
};
